import{_ as s,a0 as l,w as i,s as a,ao as p,I as n,a1 as e,A as r,x as u}from"./chunks/framework.ePQ6-oQR.js";import"./chunks/theme.D0YJYoYq.js";const U=JSON.parse('{"title":"如何创建Ubuntu 信息亭（kiosk） | LCTT x X-CMD","titleTemplate":false,"description":"如何创建Ubuntu 信息亭（kiosk） | LCTT (201409) | X-CMD","frontmatter":{"pageClass":"x-lctt","head":[["meta",{"name":"og:title","content":"如何创建Ubuntu 信息亭（kiosk） | LCTT x X-CMD"}],["meta",{"name":"og:description","content":"如何创建Ubuntu 信息亭（kiosk） | LCTT (201409) | X-CMD"}]]},"headers":[],"params":{"isLCTT":true,"post":"201409/20140801 How to Create an Ubuntu Kiosk Computer","title":"如何创建Ubuntu 信息亭（kiosk）","tag":"201409","desc":""},"relativePath":"201409/20140801 How to Create an Ubuntu Kiosk Computer.md","filePath":"[post].md"}'),k={name:"201409/20140801 How to Create an Ubuntu Kiosk Computer.md"};function b(d,t,m,f,C,T){const o=l("Link");return i(),a("div",null,[t[15]||(t[15]=p('<h1 id="如何创建ubuntu-信息亭-kiosk" tabindex="-1">如何创建Ubuntu 信息亭（kiosk） <a class="header-anchor" href="#如何创建ubuntu-信息亭-kiosk" aria-label="Permalink to “如何创建Ubuntu 信息亭（kiosk）”">​</a></h1><p><strong>Linux发行版可以作为全功能打包，也可以按需分解，它驱动了从市内标示牌到市议会桌面系统在内的所有设备。</strong></p><p>正是这种多样化，几乎可塑的质量，让Linux发行版，包括Ubuntu在内，在众多不同领域如此成功。</p><h3 id="信息亭和单功能计算机" tabindex="-1">信息亭和单功能计算机 <a class="header-anchor" href="#信息亭和单功能计算机" aria-label="Permalink to “信息亭和单功能计算机”">​</a></h3><p>Ubuntu更为流行的使用之一，是在<strong>信息亭（kiosk）类计算机</strong>中。这些设备趋向于运行功能剥离的，或者功能有限的OS版本，只允许<strong>一个单一应用运行</strong>。</p><p>信息亭计算机可以设置提供短时的或者被动的访问，适用于网吧或只能让用户访问特定功能时（如网页浏览器）。</p><h3 id="构建ubuntu信息端" tabindex="-1">构建Ubuntu信息端 <a class="header-anchor" href="#构建ubuntu信息端" aria-label="Permalink to “构建Ubuntu信息端”">​</a></h3><p>但你会怎样来创建这样一台计算机？好吧，不用去Google了。Linux开发者Oli Warner最近发布了两篇文章，介绍了使用Ubuntu 14.04和Google Chrome来创建单一功能的设备。</p><p>他的第一篇指南从零开始，使用Ubuntu Server和少量的软件包来创建一个轻量级的X和Openbox的组合，开机启动Chrome。该安装需要最多2GB的磁盘空间和仅仅512MB的内存来运行。</p>',9)),n("ul",null,[n("li",null,[e(o,{href:"http://thepcspy.com/read/building-a-kiosk-computer-ubuntu-1404-chrome"},{default:r(()=>[...t[0]||(t[0]=[u("从零开始构建信息亭计算机",-1)])]),_:1})])]),t[16]||(t[16]=n("p",null,"第二篇教程反其道而行，一步一步介绍了将一个现存的Ubuntu桌面安装转变为一个更轻巧的单一功能的变形版本。",-1)),n("ul",null,[n("li",null,[e(o,{href:"http://thepcspy.com/read/converting-ubuntu-desktop-to-kiosk/"},{default:r(()=>[...t[1]||(t[1]=[u("将Ubuntu转换成信息亭计算机",-1)])]),_:1})])]),t[17]||(t[17]=n("p",null,"两个指南都不是给那些胆小的新手的，而对于大多数中级水平的用户而言却是简单易行的。跟着指南来获得一次实用的安装体验，不要畏首畏尾，大胆去剥离一些深层次的包和进程，或者加固安全吧，特别是如果想要在公共环境中使用时。",-1)),t[18]||(t[18]=n("hr",null,null,-1)),n("p",null,[t[3]||(t[3]=u("via: ",-1)),e(o,{href:"http://www.omgubuntu.co.uk/2014/07/create-ubuntu-kiosk"},{default:r(()=>[...t[2]||(t[2]=[u("http://www.omgubuntu.co.uk/2014/07/create-ubuntu-kiosk",-1)])]),_:1})]),n("p",null,[t[7]||(t[7]=u("作者：",-1)),e(o,{href:"https://plus.google.com/117485690627814051450/?rel=author"},{default:r(()=>[...t[4]||(t[4]=[u("Joey-Elijah Sneddon",-1)])]),_:1}),t[8]||(t[8]=u(" 译者：",-1)),e(o,{href:"https://github.com/GOLinux"},{default:r(()=>[...t[5]||(t[5]=[u("GOLinux",-1)])]),_:1}),t[9]||(t[9]=u(" 校对：",-1)),e(o,{href:"https://github.com/wxy"},{default:r(()=>[...t[6]||(t[6]=[u("wxy",-1)])]),_:1})]),n("p",null,[t[12]||(t[12]=u("本文由 ",-1)),e(o,{href:"https://github.com/LCTT/TranslateProject"},{default:r(()=>[...t[10]||(t[10]=[u("LCTT",-1)])]),_:1}),t[13]||(t[13]=u(" 原创翻译，",-1)),e(o,{href:"http://linux.cn/"},{default:r(()=>[...t[11]||(t[11]=[u("Linux中国",-1)])]),_:1}),t[14]||(t[14]=u(" 荣誉推出",-1))])])}const L=s(k,[["render",b]]);export{U as __pageData,L as default};
